create extension if not exists pgcrypto;
create schema auth; create role anon nologin; create role authenticated nologin;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create table auth.users(id uuid primary key);
create table public.departments(id uuid primary key);
create table public.programs(id uuid primary key);
create table public.academic_levels(id uuid primary key,level_number int,name text,status text default 'active');
create table public.study_plans(id uuid primary key,total_credit_hours numeric not null);
create table public.courses(id uuid primary key,credit_hours numeric not null);
create table public.student_profiles(id uuid primary key,user_id uuid,program_id uuid,department_id uuid,updated_at timestamptz default now());
create table public.student_requests(id uuid primary key,student_profile_id uuid,request_type text,status text);
create table public.course_offerings(id uuid primary key,course_id uuid not null);
create table public.course_sections(id uuid primary key,course_offering_id uuid not null);
create table public.student_enrollments(id uuid primary key,course_section_id uuid not null,student_profile_id uuid not null);
create table public.grade_components(id uuid primary key,course_section_id uuid not null);
create table public.student_grades(id uuid primary key,student_enrollment_id uuid not null,grade_component_id uuid not null,status text,approved_at timestamptz);
create table public.student_course_grade_summary(enrollment_id uuid,student_profile_id uuid,course_id uuid,overall_status text);
create table public.study_plan_courses(id uuid primary key,study_plan_id uuid not null,course_id uuid not null,level_id uuid);
create table public.request_processing_units(id uuid primary key,code text unique,is_active boolean);
create table public.request_processing_roles(id uuid primary key,unit_id uuid,code text,is_active boolean);
create table public.request_processing_assignments(id uuid primary key,unit_id uuid,role_id uuid,department_id uuid,is_active boolean,user_id uuid);
create table public.student_request_workflow_steps(id uuid primary key,student_request_id uuid,status text,assigned_user_id uuid,processing_unit_id uuid,processing_role_id uuid);
create table public.transfer_request_details(request_id uuid primary key,requested_program_id uuid,requested_department_id uuid);
create function public.apply_transfer_on_approval() returns trigger language plpgsql as $$begin return new; end$$;
create trigger trg_apply_transfer_on_approval after update on public.student_requests for each row execute function public.apply_transfer_on_approval();
